<?phpdeclare(strict_types=1);use Yaleksandr\TelegramVacancyMonitor\Storage\SqliteInboxRepository;use Yaleksandr\TelegramVacancyMonitor\Storage\SqliteSchema;use Yaleksandr\TelegramVacancyMonitor\Storage\StoredMessage;require dirname(__DIR__) . '/vendor/autoload.php';$pdo = new PDO('sqlite::memory:');$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);new SqliteSchema($pdo)->ensure();new SqliteSchema($pdo)->ensure();$inbox = new SqliteInboxRepository($pdo);$first = new StoredMessage(123, 10, 'channel', -100123, 44, 'Вакансия: PHP-разработчик');if (!$inbox->applyUpdate(100, $first) || $inbox->nextOffset() !== 101) {    throw new RuntimeException('Первое сообщение или курсор не сохранены.');}$repeated = new StoredMessage(123, 11, 'channel', -100123, 44, 'Повтор');if ($inbox->applyUpdate(101, $repeated) || $inbox->nextOffset() !== 102) {    throw new RuntimeException('Повтор исходной публикации сохранён или курсор не обновлён.');}$next = new StoredMessage(123, 12, 'channel', -100123, 45, 'Следующая вакансия');if (!$inbox->applyUpdate(102, $next) || $inbox->nextOffset() !== 103) {    throw new RuntimeException('Новая публикация не сохранена.');}if ($inbox->applyUpdate(103, null) || $inbox->nextOffset() !== 104) {    throw new RuntimeException('Пропуск обновления не обновил курсор.');}// EN: An SQL failure must not move the cursor or discard earlier persisted messages.// RU: SQL-ошибка не должна менять курсор или удалять ранее сохранённые сообщения.$pdo->exec(<<<'SQL'    CREATE TRIGGER reject_bad_message BEFORE INSERT ON messages    WHEN NEW.body = 'reject'    BEGIN SELECT RAISE(ABORT, 'rejected by test trigger'); END    SQL);try {    $inbox->applyUpdate(104, new StoredMessage(123, 13, 'direct', null, null, 'reject'));    throw new RuntimeException('Ожидалось исключение SQLite.');} catch (PDOException) {    // EN: The expected failure was raised by SQLite, not silently ignored.    // RU: Ожидаемая ошибка возникла в SQLite и не была молча проигнорирована.}if ($inbox->nextOffset() !== 104 || (int) $pdo->query('SELECT COUNT(*) FROM messages')->fetchColumn() !== 2) {    throw new RuntimeException('SQL-ошибка нарушила транзакцию или сохранённые данные.');}fwrite(STDOUT, "Проверка SQLite: OK\n");
